country_event = {
	id = arkship.1
	hide_window = yes
	is_triggered_only = yes

	trigger = {
		is_nomadic = yes
	}

	immediate = {
		random_list = {
			50 = {
				modifier = {	# For the first five years you get no events so you have some time to journey around
					factor = 0
					years_passed < 5
				}
				modifier = {	# We increase events to bring you into the mid-game
					factor = 1.5
					mid_game_years_passed < 1
					years_passed >= 5
				}
				modifier = {	# A little cooldown so you don't get an event right as you join a war
					factor = 0
					has_country_flag = nomad_recent_war
				}
				modifier = {	# Block the event pool if all Arkships are in combat.
					factor = 0
					NOT = {
						any_owned_ship = {
							is_arkship_ship = yes
							is_in_combat = no
						}
					}
				}
				generate_arkship_event = yes
