carrier_event = {
	id = arkship.65
	title = "arkship.65.name"
	desc = "arkship.65.desc"
	picture = GFX_evt_operative_chase
	show_sound = event_ship_thrusters

	is_triggered_only = yes

	trigger = {
		NOT = { owner = { has_country_flag = arkship_start_your_engines } }
		owner = {
			is_gestalt = no
			count_relation = {
				count > 1
				limit = {
					is_country_type = default
					has_communications = prev
				}
			}
		}
	}

	immediate = {
		owner = {
			if = {
				limit = { # You can get this event twice per game, so the blocking flag is only temporary the first time
					NOT = { has_country_flag = had_first_race}
				}
				set_timed_country_flag = {
					flag = arkship_start_your_engines
					years = 35
				}
				set_country_flag = had_first_race
			}
			else = {
				set_country_flag = arkship_start_your_engines
			}

			while = {
				count = 4
				generate_start_your_engines_pilots = yes
			}
		}
	}

	option = {
		trigger = {
			event_target:pilot_gale_speed? = {# We are checking for the trait again so that it can show up in the event option
				OR = {
					has_trait = leader_trait_gale_speed
					has_trait = leader_trait_gale_speed_2
				}

			}
		}
		name = arkship.65.a

		event_target:pilot_gale_speed = {
			save_event_target_as = selected_pilot
		}
		random_list = {
