script:
carrier_event = {
	id = arkship.95
	title = arkship.95.name
	desc = arkship.95.desc
	picture = GFX_evt_megastructure_construction
	show_sound = event_arkship_in_crisis

	is_triggered_only = yes

	trigger = {
		owner = {
			NOR = {
				has_country_flag = under_pressure_flag
				has_country_flag = spinal_fracture_flag
				has_country_flag = arkship_faltering_core
			}
		}
		starbase = {
			OR = {
				has_starbase_module = arkship_spinal_devastator_mount
				has_starbase_module = arkship_capital_shipyard
				has_starbase_module = arkship_planetary_refinery
				has_starbase_module = arkship_stellar_igniter
				has_starbase_module = arkship_system_scanner
				has_starbase_module = arkship_exodus_jump
			}
		}
	}

	immediate = {
		owner = {
			set_country_flag = spinal_fracture_flag
		}
		save_event_target_as = fractured_spine_arkship
		add_modifier = {
			modifier = fractured_spine_mult
			days = -1
		}
	}

	option = {
		name = arkship.95.a
		allow = {
			owner = {
				resource_stockpile_compare = {
					resource = energy
					value >= 1000
				}
			}
			owner = {
				resource_stockpile_compare = {
					resource = alloys
					value >= 500
				}
			}
		}
		owner = {
			add_resource = {
				energy = -1000
			}
			add_resource = {
				alloys = -500
			}
		}
		remove_modifier = fractured_spine_mult
	}

	option = {
		name = arkship.95.b
		enable_special_project = {
			name = "ARKSHIP_SPINAL_FRACTURE_PROJECT"
			location = root
			owner = root.owner
		}
	}

	after = {
		owner = { hidden_effect = { country_event = { id = arkship.1 days = @medium_arkship_event_delay_days random = @medium_arkship_event_delay_random } } }
	}
}

