options.script:
name = arkship.130.a
owner = {
			# Psionic path: regular empire that hasn't blocked psionic ascension
			if = {
				limit = {
					# These are the same triggers used by tech_psionic_theory
					OR = { #The OR is so that Gestalts can get Zro Distillation with that Resolution
						has_shroud_dlc = yes # Shroud allows everyone to become psionic
						NOT = { has_ethic = ethic_gestalt_consciousness }
						is_active_resolution = resolution_galacticstudies_extradimensional_experimentation
						has_relic = r_zro_crystal
					}
					NOT = { has_origin = origin_mindwardens } # Except Mindwardens since they can't psionically ascend
				}
				add_tech_option_or_research_effect = {
					TECH = tech_psionic_theory
					PROGRESS = 0.25
					CATEGORY = society_research
				}
			}
			# Non-psionic regular empire
			else_if = {
				limit = { is_gestalt = no }
				add_tech_option_or_research_effect = {
					TECH = tech_synthetic_thought_patterns
					PROGRESS = 0.25
					CATEGORY = society_research
				}
			}
			# Hive empire
			else_if = {
				limit = { is_hive_empire = yes }
				add_tech_option_or_research_effect = {
					TECH = tech_collective_production_methods
					PROGRESS = 0.25
					CATEGORY = society_research
				}
			}
			# Machine empire
			else = {
				add_tech_option_or_research_effect = {
					TECH = tech_resource_processing_algorithms
					PROGRESS = 0.25
					CATEGORY = society_research
				}
			}
		}

name = arkship.130.b
owner = {
			# Sensors: next tier or physics if maxed
			switch = {
				trigger = has_technology
				tech_sensors_4 = {
					add_monthly_resource_mult = {
						resource = physics_research
						value = @tier2researchreward
						min = @tier2researchmin
						max = @tier2researchmax
					}
				}
				tech_sensors_3 = {
					add_tech_option_or_research_effect = { TECH = tech_sensors_4 PROGRESS = 0.25 CATEGORY = physics_research }
				}
				tech_sensors_2 = {
					add_tech_option_or_research_effect = { TECH = tech_sensors_3 PROGRESS = 0.25 CATEGORY = physics_research }
				}
				default = {
					add_tech_option_or_research_effect = { TECH = tech_sensors_2 PROGRESS = 0.25 CATEGORY = physics_research }
				}
			}
			# Cloaking: next tier if First Contact DLC, or physics if maxed
			if = {
				limit = { has_first_contact_dlc = yes }
				switch = {
					trigger = has_technology
					tech_cloaking_dark_matter = {
						add_monthly_resource_mult = {
							resource = physics_research
							value = @tier2researchreward
							min = @tier2researchmin
							max = @tier2researchmax
						}
					}
					tech_cloaking_3 = {
						add_tech_option_or_research_effect = { TECH = tech_cloaking_dark_matter PROGRESS = 0.25 CATEGORY = physics_research }
					}
					tech_cloaking_2 = {
						add_tech_option_or_research_effect = { TECH = tech_cloaking_3 PROGRESS = 0.25 CATEGORY = physics_research }
					}
					tech_cloaking_1 = {
						add_tech_option_or_research_effect = { TECH = tech_cloaking_2 PROGRESS = 0.25 CATEGORY = physics_research }
					}
					default = {
						add_tech_option_or_research_effect = { TECH = tech_cloaking_1 PROGRESS = 0.25 CATEGORY = physics_research }
					}
				}
			}
		}

