links.condition:
if = {
				limit = {
					NOT = { has_country_flag = arkship_breached_closed_borders_recently@event_target:breaching_nomad }
				}
				set_timed_country_flag = {
					flag = arkship_breached_closed_borders_recently@event_target:breaching_nomad
					years = 3
				}
				if = {
					limit = {
						NOT = { has_country_flag = arkship_crossing_closed_borders@event_target:breaching_nomad }
					}
					set_country_flag = arkship_crossing_closed_borders@event_target:breaching_nomad
					country_event = { id = arkship.865 }
				}
				else = {
					owner = {
						create_message = {
							type = MESSAGE_ARKSHIP_BREACHED_BORDERS
							localization = MESSAGE_ARKSHIP_BREACHED_BORDERS_DESC
							days = @toast_message_days
							target = from
						}
					}
				}
				add_opinion_modifier = {
					modifier = opinion_arkship_breaching_borders
					who = root.owner
				}
				# If you've recently been expelled, the opinion penalty is doubled.
				if = {
					limit = {
						root.owner = {
							has_truce = prev
							has_country_flag = expelled_from_@prev
						}
					}
					add_opinion_modifier = {
						modifier = opinion_arkship_breaching_borders
						who = root.owner
