		NOT = { has_fleet_flag = supress_nomad_border_notification }
		NOT = {
			from.space_owner? = { is_same_value = fromfrom.space_owner }
		}
		fromfrom.space_owner? = {
			NOT = { is_same_value = root.owner }
			OR = {
				# Either we've closed borders to them
				has_closed_borders = root.owner
				# Or recently expelled them
				root.owner = {
					has_truce = prev
					has_country_flag = expelled_from_@prev
				}
			}
			NOR = {
				is_same_value = root.owner
				AND = {
					is_fallen_empire_spiritualist = yes
					root.owner = { has_relic = r_severed_head }
				}
			}
		}
		OR = {
			is_cloaked = no
			AND = {
				is_cloaked = yes
				from.starbase? = {
					has_cloaking_detection >= root.trigger:has_cloaking_strength
				}
			}
		}
	}

	immediate = {
		root.owner = { save_event_target_as = breaching_nomad }
		fromfrom.space_owner = {
			if = {
				limit = {
