				}
				else = {
					owner = {
						create_message = {
							type = MESSAGE_ARKSHIP_BREACHED_BORDERS
							localization = MESSAGE_ARKSHIP_BREACHED_BORDERS_DESC
							days = @toast_message_days
							target = from
						}
					}
