script:
country_event = { #an enemy arkship has been destroyed
	id = arkship.1000
	hide_window = yes

	is_triggered_only = yes

	trigger = {
		is_country_type = default
		fromfromfrom = {
			is_arkship_ship = yes
		}
	}

	immediate = {
		if = {
			limit = {
				NOT = { has_country_flag = enemy_arkship_destroyed }
			}
			set_country_flag = enemy_arkship_destroyed
			country_event = { id = arkship.1005 scopes = { from = fromfromfrom } }
		}
		else = {
			owner = {
				create_message = {
					type = MESSAGE_ENEMY_ARKSHIP_DESTROYED
					localization = MESSAGE_ENEMY_ARKSHIP_DESTROYED_DESC
					days = 30
					target = fromfromfrom.solar_system
					variable = {
						type = name
						localization = SHIP
						scope = fromfromfrom
					}
				}
			}
		}
	}
}

