else_if = { ###Homicidals Destroy, Spawn Debris and Spawn Special Project
			limit = {
				from = {
					owner = { is_homicidal = yes }
				}
			}
			owner = {
				random_owned_colony = {
					limit = { is_planet_class = pc_ark }
					save_event_target_as = ark_colony
				}
				if = {
					limit = {
						is_at_war_with = root.from.owner
					}
					add_static_war_exhaustion = {
						attacker = root.from.owner
						location = event_target:ark_colony
						value_for_planet_destruction = 0.5
					}
				}
			}
			create_ambient_object = {
				type = arkship_debris_wreckage
				entity_offset_height = { min = -5 max = -5 }
				is_wreck = yes
			}
			if = {
				limit = {
					from = { owner = { is_country_type = default } }
				}
				if = {
					limit = { is_arkship_tier_1 = yes }
					last_created_ambient_object = {
						set_variable = { which = arkship_debris_tier value = 1 }
					}
				}
				else_if = {
					limit = { is_arkship_tier_2 = yes }
					last_created_ambient_object = {
						set_variable = { which = arkship_debris_tier value = 2 }
					}
				}
				else_if = {
					limit = { is_arkship_tier_3 = yes }
					last_created_ambient_object = {
						set_variable = { which = arkship_debris_tier value = 3 }
					}
				}
				last_created_ambient_object = {
					enable_special_project = {
						name = ARKSHIP_DEBRIS
						location = this
						owner = root.from.owner
					}
				}
			}
			root.owner = {
				country_event = {
					id = arkship.1010
					scopes = {
						from = from.owner
						fromfrom = root
						fromfromfrom = from
					}
				}
			}
			from.owner = {
				country_event = {
					id = arkship.1000
					scopes = {
						from = root.owner
						fromfrom = from
						fromfromfrom = root
					}
				}
			}
			destroy_ship = this
		}
