script:
ship_event = { # Spawn scavengeable debris when a homicidal empire disables an Arkship
	id = arkship.1020
	hide_window = yes

	is_triggered_only = yes

	trigger = {
		is_arkship_ship = yes
		OR = {
			NOT = { exists = from }
			from = {
				exists = owner
				owner = { is_at_war_with = root.owner }
			}
			from = {
				OR = {
					owner = { is_crisis_faction = yes }
					owner = { is_guardian_country = yes }
					owner = { is_space_critter_country = yes }
					owner = { is_hostile = root.owner }
				}
			}
		}
	}

	immediate = {
		if = {
			limit = {
				NOT = { exists = from }
			}
			create_ambient_object = {
				type = arkship_debris_wreckage
				entity_offset_height = { min = -5 max = -5 }
				is_wreck = yes
			}
			root.owner = {
				country_event = {
					id = arkship.1010
					scopes = {
						fromfrom = root
					}
				}
			}
			destroy_ship = this
		}
		else_if = { ###Homicidals Destroy, Spawn Debris and Spawn Special Project
			limit = {
				from = {
					owner = { is_homicidal = yes }
				}
			}
			owner = {
				random_owned_colony = {
					limit = { is_planet_class = pc_ark }
					save_event_target_as = ark_colony
				}
				if = {
					limit = {
						is_at_war_with = root.from.owner
					}
					add_static_war_exhaustion = {
						attacker = root.from.owner
						location = event_target:ark_colony
						value_for_planet_destruction = 0.5
					}
				}
			}
			create_ambient_object = {
				type = arkship_debris_wreckage
				entity_offset_height = { min = -5 max = -5 }
				is_wreck = yes
			}
			if = {
				limit = {
					from = { owner = { is_country_type = default } }
				}
				if = {
					limit = { is_arkship_tier_1 = yes }
					last_created_ambient_object = {
						set_variable = { which = arkship_debris_tier value = 1 }
					}
				}
				else_if = {
					limit = { is_arkship_tier_2 = yes }
					last_created_ambient_object = {
						set_variable = { which = arkship_debris_tier value = 2 }
					}
				}
				else_if = {
					limit = { is_arkship_tier_3 = yes }
					last_created_ambient_object = {
						set_variable = { which = arkship_debris_tier value = 3 }
					}
				}
				last_created_ambient_object = {
					enable_special_project = {
						name = ARKSHIP_DEBRIS
						location = this
						owner = root.from.owner
					}
				}
			}
			root.owner = {
				country_event = {
					id = arkship.1010
					scopes = {
						from = from.owner
						fromfrom = root
						fromfromfrom = from
					}
				}
			}
			from.owner = {
				country_event = {
					id = arkship.1000
					scopes = {
						from = root.owner
						fromfrom = from
						fromfromfrom = root
					}
				}
			}
			destroy_ship = this
		}
		else_if = { ###Crisis Destroy, Spawn Debris no Special Project
			limit = {
				from = {
					owner = { is_crisis_faction = yes }
				}
			}
			owner = {
				random_owned_colony = {
					limit = { is_planet_class = pc_ark }
					save_event_target_as = ark_colony
				}
				add_static_war_exhaustion = {
					attacker = root.from.owner
					location = event_target:ark_colony
					value_for_planet_destruction = 0.5
				}
			}
			create_ambient_object = {
				type = arkship_debris_wreckage
				entity_offset_height = { min = -5 max = -5 }
				is_wreck = yes
			}
			root.owner = {
				country_event = {
					id = arkship.1010
					scopes = {
						from = from.owner
						fromfrom = root
						fromfromfrom = from
					}
				}
			}
			from.owner = {
				country_event = {
					id = arkship.1000
					scopes = {
						from = root.owner
						fromfrom = from
						fromfromfrom = root
					}
				}
			}
			destroy_ship = this
		}
		else_if = { ###Critters, Leviathans, and other hostile non-war attackers disable and move one system
			limit = {
				from = {
					OR = {
						owner = { is_guardian_country = yes }
						owner = { is_space_critter_country = yes }
						AND = {
							owner = { is_hostile = root.owner }
							NOT = { owner = { is_at_war_with = root.owner } }
						}
					}
				}
			}
			owner = {
				random_owned_colony = {
					limit = { is_planet_class = pc_ark }
					save_event_target_as = ark_colony
				}
			}
			solar_system = {
				random_neighbor_system = {
					limit = {
						NOT = {
							any_fleet_in_system = {
								exists = owner
								owner = { is_hostile = root.owner }
							}
						}
					}
					save_event_target_as = nomad_escape_system
				}
			}
			if = {
				limit = { exists = event_target:nomad_escape_system }
				fleet = {
					set_location = event_target:nomad_escape_system
				}
			}
			ship = {
				set_ship_flag = disabled_by_gatekeeper_event
			}
			if = {
				limit = {
					owner = {
						has_origin = origin_heirs_of_the_khan
					}
					from = {
						fleet = {
							has_fleet_flag = heirs_hunter_fleet
						}
						owner = {
							has_country_flag = heirs_marauder_hunters
						}
					}
				}
				heirs_hunter_retreat_effect = yes
				if = {
					limit = { is_arkship_tier_1 = yes }
					owner = {
						add_resource = {
							energy = -150
							minerals = -150
							alloys = -75
							food = -75
						}
					}
				}
				else_if = {
					limit = { is_arkship_tier_2 = yes }
					owner = {
						add_resource = {
							energy = -600
							minerals = -600
							alloys = -300
							food = -300
						}
					}
				}
				else_if = {
					limit = { is_arkship_tier_3 = yes }
					owner = {
						add_resource = {
							energy = -1000
							minerals = -1000
							alloys = -500
							food = -500
						}
					}
				}
				owner = {
					create_message = {
						type = MESSAGE_ARKSHIP_RAIDED_BY_HUNTERS
						localization = MESSAGE_ARKSHIP_RAIDED_BY_HUNTERS_DESC
						days = 30
						target = root.solar_system
						variable = {
							type = name
							localization = SHIP
							scope = root
						}
						variable = {
							type = name
							localization = ATTACKER
							scope = from.owner
						}
					}
				}
			}
			owner = {
				country_event = {
					id = arkship.1021
					days = 5
				}
			}
		}
		else = {
			owner = {
				random_owned_colony = {
					limit = { is_planet_class = pc_ark }
					save_event_target_as = ark_colony
				}
				add_static_war_exhaustion = {
					attacker = root.from.owner
					location = event_target:ark_colony
					value_for_planet_destruction = 0.2
				}
			}
			# Note: event_target:ark_colony is a random pc_ark colony; multi-Arkship owners may not match the disabled ship's specific colony.
			if = {
				limit = {
					exists = event_target:ark_colony
					from = {
						owner = {
							is_nomadic = no
							has_policy_flag = arkship_raid_relocate_pops
							capital_scope? = {
								NOR = {
									is_planet_class = pc_machine
									is_planet_class = pc_hive
								}
							}
						}
					}
				}
				from.owner.capital_scope = {
					save_event_target_as = arkship_raid_capital
				}
				event_target:ark_colony = {
					every_owned_pop_group = {
						limit = { pop_group_size > 0 }
						save_event_target_as = arkship_raid_source_pop
						event_target:arkship_raid_capital = {
							create_pop_group = {
								pop_group = event_target:arkship_raid_source_pop
								size = 0
								effect = {
									transfer_pop_amount = {
										source = event_target:arkship_raid_source_pop
										target = this
										percentage = 0.25
									}
								}
							}
						}
					}
				}
				owner = {
					add_opinion_modifier = {
						who = from.owner
						modifier = opinion_arkship_raid_conscripted
					}
				}
			}
			else_if = {
				limit = {
					exists = event_target:ark_colony
					from = {
						owner = {
							is_nomadic = no
							has_policy_flag = arkship_raid_purge_pops
						}
					}
				}
				event_target:ark_colony = {
					every_owned_pop_group = {
						limit = { pop_group_size > 0 }
						kill_pop_group = {
							pop_group = this
							percentage = 0.25
						}
					}
				}
				owner = {
					add_opinion_modifier = {
						who = from.owner
						modifier = opinion_arkship_raid_purged
					}
				}
			}
			else_if = {
				limit = {
					exists = event_target:ark_colony
					from = {
						owner = {
							is_nomadic = no
							has_policy_flag = arkship_raid_strip_districts
						}
					}
				}
				event_target:ark_colony = {
					set_variable = { which = arkship_districts_stripped value = 0 }
					export_trigger_value_to_variable = {
						trigger = num_districts
						parameters = { type = any }
						variable = arkship_districts_stripped
					}
					divide_variable = { which = arkship_districts_stripped value = 4 }
					while = {
						count = arkship_districts_stripped
						remove_random_district = yes
					}
				}
				from.owner = {
					add_resource = {
						alloys = 150
						mult = event_target:ark_colony.arkship_districts_stripped
					}
				}
				event_target:ark_colony = {
					clear_variable = arkship_districts_stripped
				}
				owner = {
					add_opinion_modifier = {
						who = from.owner
						modifier = opinion_arkship_raid_stripped
					}
				}
			}
			ship = {
				set_ship_flag = disabled_by_default_empire_event
			}
			fleet = {
				set_controller = from.owner
			}
		}
	}
}

