country_event = {
	id = arkship.1026
	hide_window = yes
	is_triggered_only = yes

	immediate = {
		if = {
			limit = { exists = from }
			# Arkship: regain control (reverses a seize; ownership is fleet-level), then re-enable.
			if = {
				limit = {
					from = {
						is_arkship_fleet = yes
						any_owned_ship = { is_arkship_ship = yes is_disabled = yes }
					}
				}
				from = {
					set_owner = root
					every_owned_ship = {
						limit = { is_arkship_ship = yes is_disabled = yes }
						repair_amount = 1000
						set_disabled = no
						remove_ship_flag = disabled_by_default_empire_event
					}
					set_controller = root	# end enemy occupation; set_owner alone leaves control with the occupier
				}
			}
			# Waystation: re-enable only (no ownership restore, per design).
			else_if = {
				limit = {
					from = { any_owned_ship = { is_waystation_ship = yes is_disabled = yes } }
				}
				from = {
					every_owned_ship = {
						limit = { is_waystation_ship = yes is_disabled = yes }
						repair_amount = 1000
						set_disabled = no
					}
				}
			}
			from = { remove_fleet_flag = nomad_recovery_project_active }
		}
	}
}

