starbase_event = {
	id = arkship.1027
	hide_window = yes
	is_triggered_only = yes

	trigger = {
		OR = {
			is_arkship_starbase = yes
			is_waystation_starbase = yes
		}
		owner? = {
			is_nomadic = yes
			is_at_war = yes
		}
	}

	immediate = {
		owner = { save_event_target_as = nomad_recovery_owner }
		solar_system = {
			# The fleet flag guard ensures that if several vessels are disabled in the
			# same system, each on_starbase_disabled firing picks a different one (and
			# prevents a second project on a fleet that already has one).
			random_fleet_in_system = {
				limit = {
					owner = { is_same_value = event_target:nomad_recovery_owner }
					NOT = { has_fleet_flag = nomad_recovery_project_active }
					OR = {
						AND = {
							is_arkship_fleet = yes
							any_owned_ship = { is_arkship_ship = yes is_disabled = yes }
						}
						any_owned_ship = { is_waystation_ship = yes is_disabled = yes }
					}
				}
				set_fleet_flag = nomad_recovery_project_active
				enable_special_project = {
					name = RECOVER_DISABLED_NOMAD_VESSEL
					location = this				# the disabled fleet
					owner = event_target:nomad_recovery_owner
				}
			}
		}
	}
}

